```yaml
name: Claude Code

on:
  workflow_dispatch:
    inputs:
      issue_number:
        description: 'Issue number to address'
        required: true
        type: string
      instructions:
        description: 'Additional instructions for Claude Code'
        required: false
        type: string

permissions:
  contents: read
  issues: read
  pull-requests: write

concurrency:
  group: ${{ github.workflow }}-${{ github.ref }}
  cancel-in-progress: true

jobs:
  claude-code:
    runs-on: ubuntu-latest
    timeout-minutes: 30
    steps:
      - name: Check maintainer permissions
        id: check_permissions
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const actor = context.actor;

            try {
              // Check if actor is a collaborator
              const response = await github.rest.repos.checkCollaborator({
                owner,
                repo,
                username: actor
              });

              if (response.status === 204) {
                console.log(`${actor} is a collaborator`);
                return true;
              }
            } catch (error) {
              if (error.status === 404) {
                console.log(`${actor} is NOT a collaborator`);
                core.setFailed(`User ${actor} is not a repository collaborator`);
                return false;
              }
              throw error;
            }

      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Setup pnpm
        uses: ./.github/actions/pnpm-setup

      - name: Get issue details
        id: get_issue
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const issueNumber = `${{ github.event.inputs.issue_number }}`;

            try {
              const response = await github.rest.issues.get({
                owner,
                repo,
                issue_number: parseInt(issueNumber)
              });

              const issueTitle = response.data.title;
              const issueBody = response.data.body || '';

              core.setOutput('issue_title', issueTitle);
              core.setOutput('issue_body', issueBody);
              core.setOutput('issue_url', response.data.html_url);
            } catch (error) {
              core.setFailed(`Failed to fetch issue ${issueNumber}: ${error.message}`);
            }

      - name: Run Claude Code
        id: claude
        uses: anthropics/claude-code-base-action@beta
        with:
          prompt: |
            You are an expert TypeScript developer working on the Liam project. Your task is to address the following issue:

            Issue Number: ${{ github.event.inputs.issue_number }}
            Issue Title: ${{ steps.get_issue.outputs.issue_title }}
            Issue Description: ${{ steps.get_issue.outputs.issue_body }}
            Issue URL: ${{ steps.get_issue.outputs.issue_url }}

            Additional Instructions: ${{ github.event.inputs.instructions }}

            Please analyze the codebase and implement a solution that addresses this issue. Focus on:
            1. Following existing code patterns and conventions
            2. Maintaining type safety
            3. Writing clean, readable code
            4. Adding appropriate comments where necessary
            5. Ensuring all tests pass

            If you need to make changes to multiple files, please explain your approach clearly.

            When making changes, use the following approach:
            - Identify the root cause of the issue
            - Implement a minimal, focused fix
            - Ensure backward compatibility
            - Follow the existing code style and patterns
            - Add any necessary documentation or comments
          anthropic_api_key: ${{ secrets.ANTHROPIC_API_KEY }}
          model: claude-3-5-sonnet-20241022
          timeout_minutes: 20

      - name: Create draft pull request
        if: steps.claude.outputs.conclusion == 'success'
        uses: peter-evans/create-pull-request@v7
        with:
          token: ${{ secrets.GITHUB_TOKEN }}
          commit-message: "feat: address issue ${{ github.event.inputs.issue_number }} with Claude Code"
          branch: "claude-code/issue-${{ github.event.inputs.issue_number }}-${{ github.run_id }}"
          delete-branch: true
          title: "feat: address issue ${{ github.event.inputs.issue_number }} with Claude Code"
          body: |
            This pull request was automatically generated by Claude Code to address issue #${{ github.event.inputs.issue_number }}.

            **Issue Details:**
            - Title: ${{ steps.get_issue.outputs.issue_title }}
            - Description: ${{ steps.get_issue.outputs.issue_body }}
            - URL: ${{ steps.get_issue.outputs.issue_url }}

            **Additional Instructions:**
            ${{ github.event.inputs.instructions }}

            This is a draft PR. Please review the changes carefully before merging.

            [Claude Code Execution Result](https://github.com/${{ github.repository }}/actions/runs/${{ github.run_id }})
          draft: true
          labels: |
            claude-code
            automated-pr
```

